```javascript
const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let lines = [];
let lineCount = 0;

rl.on('line', (line) => {
    lines.push(line);
    lineCount++;
    if (lineCount === 1) {
        const tokens = line.split(/\s+/).map(Number);
        const n = tokens[0];
        const l = tokens[1] * tokens[2];
        const d = tokens[3] * tokens[4];
        const p = tokens[5];
        const nl = n * tokens[6];
        const nd = n;
        const np = n * tokens[7];

        const c = [
            Math.floor(l / nl),
            Math.floor(d / nd),
            Math.floor(p / np)
        ];

        c.sort((a, b) => a - b);
        console.log(c[0]);
        rl.close();
    }
});
```

